import stylesText from './log-block.css?inline';
import { cssStyleSheet } from '../../../../utils/css.js';
import { formatMacro, macroSegments } from '../../../../utils/format-macro.js';
import { logLineView, viewNutrition } from '../../../../utils/line-view.js';
import { formatTotal, totalsOf } from '../../../../utils/nutrition-totals.js';
import type { LogWithLines } from '@motivation/shared';
import { HEALTH_EVENTS, createLineOpenEvent, createLogMenuEvent, type LineOpenEvent } from '../../health-events.js';
import { FilesService } from '../../../../services/files.service.js';
import '../../food-thumbnail/food-thumbnail.component.js';
import '../line-row/line-row.component.js';
import type { LineRow } from '../line-row/line-row.component.js';

const styles = cssStyleSheet(stylesText);

const MORE_SVG = `<svg width="22" height="22" viewBox="0 0 24 24" fill="currentColor" aria-hidden="true"><circle cx="5" cy="12" r="2"/><circle cx="12" cy="12" r="2"/><circle cx="19" cy="12" r="2"/></svg>`;
const CHEVRON_SVG = `<svg class="chevron" width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M6 9l6 6 6-6"/></svg>`;

const template = document.createElement('template');
template.innerHTML = `
    <div class="head">
        <img class="banner" alt="" loading="lazy" decoding="async" hidden>
        <button type="button" class="toggle" aria-expanded="false">
            <span class="time" hidden></span>
            <food-thumb></food-thumb>
            <span class="text">
                <span class="name"></span>
                <span class="sub"></span>
            </span>
            <span class="kcal"></span>
            ${CHEVRON_SVG}
        </button>
        <button type="button" class="more">${MORE_SVG}</button>
    </div>
    <div class="lines" role="list" hidden></div>
`;

/**
 * Story 422 (418 #10) — a log of several lines on the day: a collapsed block whose header
 * toggles it open, a ⋯ that asks for the log's menu (`health:log-menu`), and its lines read-only
 * — tapping one opens it (`health:line-open` with the log's id). Set `.log`; `time` is the
 * eaten-at HH:MM the day renders.
 */
export class LogBlock extends HTMLElement {
    static get observedAttributes() { return ['time', 'open']; }

    private logValue: LogWithLines | null = null;
    /** A cover that would not load: the block falls back to its first photo, not a broken banner. */
    private failedCover: string | null = null;

    constructor() {
        super();
        const shadow = this.attachShadow({ mode: 'open' });
        shadow.adoptedStyleSheets = [styles];
        shadow.appendChild(template.content.cloneNode(true));
        customElements.upgrade(shadow);
        const banner = shadow.querySelector('.banner') as HTMLImageElement;
        banner.addEventListener('error', () => {
            this.failedCover = this.logValue?.meal_image_path ?? null;
            this.render();
        });
        shadow.querySelector('.toggle')!.addEventListener('click', () => this.toggleAttribute('open'));
        shadow.querySelector('.more')!.addEventListener('click', () => {
            if (this.logValue) this.dispatchEvent(createLogMenuEvent({ log_id: this.logValue.id }));
        });
        // A line here belongs to this log: say which.
        shadow.querySelector('.lines')!.addEventListener(HEALTH_EVENTS.LINE_OPEN, (e: Event) => {
            const event = e as LineOpenEvent;
            if (event.detail.log_id !== undefined || !this.logValue) return;
            e.stopPropagation();
            this.dispatchEvent(createLineOpenEvent({ key: event.detail.key, log_id: this.logValue.id }));
        });
    }

    get log(): LogWithLines | null { return this.logValue; }
    set log(value: LogWithLines) {
        this.logValue = value;
        this.render();
    }

    attributeChangedCallback(): void { this.render(); }
    connectedCallback(): void { this.render(); }

    private render(): void {
        const shadow = this.shadowRoot!;
        const open = this.hasAttribute('open');
        (shadow.querySelector('.toggle') as HTMLElement).setAttribute('aria-expanded', String(open));
        (shadow.querySelector('.lines') as HTMLElement).hidden = !open;
        const time = shadow.querySelector('.time') as HTMLElement;
        time.hidden = !this.hasAttribute('time');
        time.textContent = this.getAttribute('time') ?? '';
        const log = this.logValue;
        if (!log) return;

        const views = log.lines.map(logLineView);
        const t = totalsOf(views.map(viewNutrition));
        const name = log.name ?? log.lines[0]?.food_name ?? 'Log';
        (shadow.querySelector('.name') as HTMLElement).textContent = name;
        (shadow.querySelector('.sub') as HTMLElement).replaceChildren(...macroSegments(
            `${log.lines.length} items · P ${formatTotal(t.protein_g)} · C ${formatTotal(t.carbs_g)} · F ${formatTotal(t.fat_g)}`));
        (shadow.querySelector('.kcal') as HTMLElement).textContent = formatTotal(t.calories);
        const thumb = shadow.querySelector('food-thumb') as HTMLElement;
        const photo = log.lines.find((l) => l.image_path)?.image_path ?? null;
        // Story 431 (127's banner): a log from a meal with a cover wears it; the thumb gives way.
        const banner = shadow.querySelector('.banner') as HTMLImageElement;
        const cover = log.meal_image_path && log.meal_image_path !== this.failedCover ? log.meal_image_path : null;
        this.toggleAttribute('banner', cover !== null);
        banner.hidden = cover === null;
        if (cover) banner.src = FilesService.variantUrl(cover, 'display.jpg'); else banner.removeAttribute('src');
        if (photo && !cover) thumb.setAttribute('path', photo); else thumb.removeAttribute('path');
        (shadow.querySelector('.more') as HTMLElement).setAttribute('aria-label', `Actions for ${name}`);
        (shadow.querySelector('.toggle') as HTMLElement).setAttribute('aria-label', `${name}, ${log.lines.length} items, ${formatMacro(t.calories.value)} kcal`);

        const lines = shadow.querySelector('.lines') as HTMLElement;
        const byKey = new Map([...lines.querySelectorAll<LineRow>('line-row')].map((r) => [r.line?.key, r]));
        lines.replaceChildren(...views.map((view) => {
            const row = byKey.get(view.key) ?? (document.createElement('line-row') as LineRow);
            row.setAttribute('role', 'listitem');
            row.line = view;
            return row;
        }));
    }
}

if (!customElements.get('log-block')) {
    customElements.define('log-block', LogBlock);
}
