export class HealthDayScreen extends HTMLElement implements ScreenComponent {
    private initialized = false;
    private detail: HealthDayDetail | null = null;
    private quickLog: HTMLElement | null = null;
    private loadSequence = 0;
    private dateValue = '';
    private activeTabValue: DayTab = DEFAULT_DAY_TAB;
    private moreMenuOpen = false;
    /** Story 378: the Log Activity start default, computed as the dialog opens. */
    private openStartDefault: () => void = () => {};
    private dialogHost: HTMLElement | null = null;
    private hcPanel: HcSyncPanel | null = null;
    private logMenu: LogMenu | null = null;
    /** The day's logs as last rendered — what the ⋯ menu acts on. */
    private logs: LogWithLines[] = [];
    private readonly log = createComponentLogger('health-day-screen');

    set date(value: string) {
        this.dateValue = value;
    }

    /**
     * Story 289: the tab the day opens on, from `?tab=`. Only the initial tab —
     * once mounted, the detail owns the choice and syncs the URL itself.
     */
    set activeTab(value: DayTab) {
        this.activeTabValue = value;
    }

    setLoading(): void {
        this.detail?.showLoading();
    }

    setError(err: unknown): void {
        if (err instanceof Error) {
            this.detail?.showError(err.stack ?? err.message);
        } else {
            this.detail?.showError(String(err));
        }
    }

    clearStatus(): void {
        this.detail?.hideLoading();
    }

    connectedCallback(): void {
        if (!this.initialized) {
            this.initialized = true;

            const page = buildSectionPage(this, 'Health', 'health', '/health');

            // Story 173/258: the way into the coaching note is the 💬 chip in
            // the day-detail header (the briefing keyed by day D is the one
            // written on the morning of D looking ahead to it).
            this.detail = document.createElement('health-day-detail') as HealthDayDetail;
            this.detail.dateContext = this.dateValue;
            this.detail.activeTab = this.activeTabValue;
            this.detail.showLoading();
            page.content.appendChild(this.detail);

            // Story 258: the quick-log bar logs to the *viewed* date; the `›`
            // opens the same more-actions menu as the dashboard.
            this.quickLog = document.createElement('quick-log-bar');
            this.quickLog.className = 'day-quick-log';
            this.quickLog.setAttribute('date', this.dateValue);
            page.content.appendChild(this.quickLog);

            this.dialogHost = document.createElement('div');
            page.content.appendChild(this.dialogHost);
            this.dialogHost.appendChild(moreMenuTemplate.content.cloneNode(true));
            this.dialogHost.appendChild(addActivityTemplate.content.cloneNode(true));
            this.dialogHost.appendChild(hcSyncTemplate.content.cloneNode(true));
            this.logMenu = document.createElement('log-menu') as LogMenu;
            this.dialogHost.appendChild(this.logMenu);

            this.wireDetail();
            this.wireMoreMenu();
            this.wireAddDialog();
            this.wireHcSyncDialog();
        }

        if (this.detail) {
            this.detail.dateContext = this.dateValue;
        }
        this.quickLog?.setAttribute('date', this.dateValue);
        void this.loadData();
    }

    private wireDetail(): void {
        if (!this.detail) return;
        this.detail.addEventListener(HEALTH_EVENTS.ADD_WORKOUT, (event: AddWorkoutEvent) => {
            this.openManualAddDialog(event.detail.date);
        });

        this.detail.addEventListener(HEALTH_EVENTS.ADD_FOOD, (event: AddFoodEvent) => {
            navigate(`/health/log/new/${encodeURIComponent(event.detail.date)}/${encodeURIComponent(event.detail.meal)}`);
        });

        // 418 #9: tapping a line edits that line, on its own route.
        this.detail.addEventListener(HEALTH_EVENTS.LINE_OPEN, (event: LineOpenEvent) => {
            if (!event.detail.log_id) return;
            navigate(`/health/log/${encodeURIComponent(event.detail.log_id)}/line/${encodeURIComponent(event.detail.key)}`);
        });

        // Story 430: logs picked on the day become one meal, in the meal editor.
        this.detail.addEventListener(HEALTH_EVENTS.SAVE_LOGS_AS_MEAL, (event: SaveLogsAsMealEvent) => {
            navigate(`/health/meals/new?logs=${event.detail.log_ids.map(encodeURIComponent).join(',')}`);
        });

        // 418 #10: a log's ⋯ menu.
        this.detail.addEventListener(HEALTH_EVENTS.LOG_MENU, (event: LogMenuEvent) => {
            const log = this.logs.find((l) => l.id === event.detail.log_id);
            if (log) this.logMenu?.open(log);
        });
        this.logMenu?.addEventListener(HEALTH_EVENTS.LOG_ACTION, (event: LogActionEvent) => {
            void this.applyLogAction(event.detail.log_id, event.detail.action);
        });

        this.detail.addEventListener(HEALTH_EVENTS.EDIT_WORKOUT, (event: EditWorkoutEvent) => {
            navigate(`/health/activity/${encodeURIComponent(event.detail.activity.id)}`);
        });

        // Story 323. `silent` because the cards are a list and a loading indicator that reflows
        // between mousedown and mouseup steals the next tap (design log #255, story 288's lesson);
        // the button disables itself as the feedback instead. Failures still surface loudly.
        this.detail.addEventListener(HEALTH_EVENTS.ADOPT_CALENDAR_ACTIVITY, (event: AdoptCalendarActivityEvent) => {
            // Story 371: answered, so the button stays disabled until the POST lands.
            event.detail.respondWith = safeExec(this, this.log, async () => {
                await adoptCalendarActivityAndOpenHub(event.detail.activity);
            }, { silent: true, errorMessage: 'Could not log this calendar class' });
        });

    }

    /** A ⋯ menu choice: one write each, then the day again (418 #3 — a log is one record). */
    private async applyLogAction(logId: string, action: LogMenuAction): Promise<void> {
        if (action.kind === 'edit') {
            navigate(`/health/log/${encodeURIComponent(logId)}`);
            return;
        }
        const log = this.logs.find((l) => l.id === logId);
        if (!log) return;
        await this.mutateMeal(async () => {
            if (action.kind === 'scale') await HealthService.scaleLog(logId, action.factor);
            // Story 260: a stamp keeps its wall-clock time in the zone this client renders.
            else if (action.kind === 'move') await HealthService.updateLog(logId, { date: action.date, meal_type: action.meal_type, time_zone: getAppTimeZone() });
            else if (action.kind === 'delete') await HealthService.deleteLog(logId);
            else await HealthService.createMeal({ name: action.name, ingredients: mealIngredientsOf(log) });
        });
    }

    // The `›` menu — same options as the dashboard's, except Log Activity
    // pre-fills the *viewed* date instead of today.
    private wireMoreMenu(): void {
        this.addEventListener(HEALTH_EVENTS.QUICK_LOG_MORE, () => this.toggleMoreMenu());

        this.querySelector<HTMLButtonElement>('#more-food')!.addEventListener('click', () => {
            this.closeMoreMenu();
            // Story 422: the viewed day, the slot for now; the bar's slot buttons pick another.
            navigate(addFoodPath(this.dateValue));
        });
        this.querySelector<HTMLButtonElement>('#more-activity')!.addEventListener('click', () => {
            this.closeMoreMenu();
            this.openManualAddDialog(this.dateValue);
        });
        this.querySelector<HTMLButtonElement>('#more-template')!.addEventListener('click', () => {
            this.closeMoreMenu();
            navigate('/health/workout-templates');
        });
        this.querySelector<HTMLButtonElement>('#more-weight')!.addEventListener('click', () => {
            this.closeMoreMenu();
            navigate('/health/weight');
        });
        this.querySelector<HTMLButtonElement>('#more-meals')!.addEventListener('click', () => {
            this.closeMoreMenu();
            navigate('/health/meals');
        });
        this.querySelector<HTMLButtonElement>('#more-foods')!.addEventListener('click', () => {
            this.closeMoreMenu();
            navigate('/health/foods');
        });
        this.querySelector<HTMLButtonElement>('#more-hc-sync')!.addEventListener('click', () => {
            this.closeMoreMenu();
            this.openHcSyncDialog();
        });
    }

    // Story 307: both day entry points — the Activity tab's ⟳ button and the `›`
    // menu — open the same dialog, and the panel inside it is the same element
    // the Status screen mounts.
    private wireHcSyncDialog(): void {
        this.addEventListener(HEALTH_EVENTS.HC_SYNC_REQUEST, () => this.openHcSyncDialog());

        // A sync that changed stored rows means the day on screen is stale — and
        // this fires even if the dialog was closed mid-sync, because the panel
        // stays mounted once created.
        this.addEventListener(HEALTH_EVENTS.HC_SYNC_APPLIED, () => void this.loadData());

        const dialog = this.querySelector<HTMLDialogElement>('#hc-sync-dialog');
        this.querySelector<HTMLButtonElement>('#hc-sync-close')!.addEventListener('click', () => dialog?.close());
        dialog?.addEventListener('close', () => {
            if (this.hcPanel) this.hcPanel.active = false;
            this.detail?.refreshHcLastSynced();
        });
    }

    private openHcSyncDialog(): void {
        const dialog = this.querySelector<HTMLDialogElement>('#hc-sync-dialog');
        if (!dialog) return;
        if (!this.hcPanel) {
            this.hcPanel = document.createElement('hc-sync-panel') as HcSyncPanel;
            this.querySelector<HTMLDivElement>('#hc-sync-body')!.appendChild(this.hcPanel);
        }
        this.hcPanel.active = true;
        dialog.showModal();
    }

    private toggleMoreMenu(): void {
        this.moreMenuOpen = !this.moreMenuOpen;
        this.querySelector<HTMLElement>('#more-menu')!.hidden = !this.moreMenuOpen;
    }

    private closeMoreMenu(): void {
        this.moreMenuOpen = false;
        this.querySelector<HTMLElement>('#more-menu')!.hidden = true;
    }

    // Run a logged-meal mutation, then re-render — both inside one safeExec so a
    // failed mutation surfaces its raw error instead of being papered over by the
    // follow-up refresh (safeExec swallows on error and does not rethrow).
    private async mutateMeal(op: () => Promise<unknown>): Promise<void> {
        return safeExec(this, this.log, async () => {
            await op();
            await this.fetchAndRender();
        }, { errorMessage: 'Failed to update meal' });
    }

    private wireAddDialog(): void {
        const dialog = this.querySelector<HTMLDialogElement>('#activity-dialog');
        const form = this.querySelector<HTMLFormElement>('#activity-form');
        if (!dialog || !form) return;
        this.openStartDefault = wireStartTimeDefault(form);

        dialog.addEventListener('close', () => {
            try {
                if (dialog.returnValue !== 'save') return;

                const data = Object.fromEntries(new FormData(form)) as Record<string, string>;
                if (!data.title || !data.date) return;

                void this.saveManualActivity({
                    title: data.title,
                    type: data.type,
                    date: data.date,
                    duration_minutes: data.duration ? parseInt(data.duration, 10) : undefined,
                    start_time: data.start || undefined,
                });
            } finally {
                form.reset();
            }
        });
    }

    private async saveManualActivity(data: {
        title: string;
        type: string;
        date: string;
        duration_minutes?: number;
        start_time?: string;
    }): Promise<void> {
        return safeExec(this, this.log, async () => {
            // Land on the hub (story 181) — attach a workout/cardio there rather
            // than branching on type here.
            await createActivityAndOpenHub(data);
        });
    }

    private openManualAddDialog(date: string): void {
        const dialog = this.querySelector<HTMLDialogElement>('#activity-dialog');
        const dateInput = this.querySelector<HTMLInputElement>('#act-date');
        if (dialog && dateInput) {
            dateInput.value = date;
            this.openStartDefault();
            showModalFresh(dialog);
        }
    }

    private async loadData(): Promise<void> {
        if (!this.detail) return;
        return safeExec(this, this.log, () => this.fetchAndRender(), { errorMessage: `Failed to load detail for ${this.dateValue}` });
    }

    // The raw fetch + render, without status handling — it throws on failure so
    // the caller's safeExec surfaces it. Shared by loadData() and mutateMeal().
    private async fetchAndRender(): Promise<void> {
        if (!this.detail) return;

        const currentLoad = ++this.loadSequence;
        this.detail.dateContext = this.dateValue;

        const day = Temporal.PlainDate.from(this.dateValue);
        const [activities, logs, daySteps, weights, lookback] = await Promise.all([
            HealthService.getActivitiesByDate(this.dateValue),
            // 421: a log's lines carry their own name, unit, photo and nutrition — nothing else to fetch (164).
            HealthService.getLogsByDate(this.dateValue),
            // Story 258: steps + weights (MET-estimate body weight) + a
            // lookback window for the "time since 🏋️/🏃/🚴" widget row.
            HealthService.getDailySteps(this.dateValue, this.dateValue),
            HealthService.getWeightByDateRange(day.subtract({ days: WEIGHT_LOOKBACK_DAYS }).toString(), this.dateValue),
            HealthService.getMeaningfulActivitiesByDateRange(day.subtract({ days: TIME_SINCE_LOOKBACK_DAYS }).toString(), this.dateValue),
        ]);

        if (currentLoad !== this.loadSequence || !this.detail) return;

        // Story 258: burn (real-or-estimated) per activity and for the day.
        const weightKg = weightKgOnDate(weights, this.dateValue);
        const burnByActivityId = new Map(
            activities.flatMap((activity) => {
                const burn = activityBurnKcal(activity, weightKg);
                return burn ? [[activity.id, burn] as const] : [];
            }),
        );
        this.detail.burnByActivityId = burnByActivityId;
        this.detail.dayBurn = dayBurnKcal(activities, weightKg);
        this.detail.steps = daySteps.find((s) => s.date === this.dateValue)?.steps ?? null;
        // Story 374: a booked class has not happened yet — it is no "last time" either.
        const happened = happenedActivities(lookback);
        this.detail.lastActivityDays = {
            weight_training: daysSinceLastOfType(happened, 'weight_training', day),
            running: daysSinceLastOfType(happened, 'running', day),
            cycling: daysSinceLastOfType(happened, 'cycling', day),
        };

        this.detail.activities = activities;
        this.logs = logs;
        this.detail.logs = logs;
        this.detail.showContent();
    }

}

if (!customElements.get('health-day-screen')) {
    customElements.define('health-day-screen', HealthDayScreen);
}
