import stylesText from './activity-detail-card.css?inline';
import { cssStyleSheet } from '../../../utils/css.js';
import { formatMacro } from '../../../utils/format-macro.js';

const styles = cssStyleSheet(stylesText);
import type { Activity } from '@motivation/shared';
import { isSynthesizedCalendarEvent } from '@motivation/shared';
import { activityIcon, activityStartLocalTime } from '../health-utils.js';
import { whileBusy } from '../../../utils/in-flight.js';

const SOURCE_ICONS: Record<string, string> = {
    manual: '✏️',
    strava: '🟧',
    calendar: '📅',
    // Story 250: Health Connect ingest — orange square for Strava-recorded, green heart for Google Fit.
    health_connect_strava: '🟧',
    health_connect_android_fitness: '💚',
    // Story 298: the Google Health app, a third HC writer since 2026-08-20. Distinct badge so it
    // is visible which app recorded an activity as Google Fit is retired.
    health_connect_google_health: '🩵',
};

const template = document.createElement('template');
template.innerHTML = `
    <div class="detail-card">
        <div class="card-left">
            <div class="type-icon" id="type-icon"></div>
        </div>
        <div class="card-body">
            <div class="card-title" id="title"></div>
            <div class="card-meta" id="meta"></div>
        </div>
        <div class="card-right">
            <button type="button" class="adopt-btn" id="adopt" hidden>I was there</button>
            <span class="source-badge" id="source-badge" title=""></span>
        </div>
    </div>
`;

export class ActivityDetailCard extends HTMLElement {
    private _activity: Activity | null = null;
    private _estimatedBurnKcal: number | null = null;
    private _onAdopt: ((activity: Activity) => void | Promise<void>) | null = null;

    constructor() {
        super();
        const shadow = this.attachShadow({ mode: 'open' });
        shadow.adoptedStyleSheets = [styles];
        shadow.appendChild(template.content.cloneNode(true));
        shadow.getElementById('adopt')!.addEventListener('click', (e) => {
            // The card itself is a click target for rows that have somewhere to go; an adopt tap
            // is not also a navigation.
            e.stopPropagation();
            void this.handleAdopt();
        });
    }

    /**
     * Called when the owner confirms they attended a calendar class (story 323). Setting it is
     * what reveals the button, and only on a row that has no stored record yet.
     */
    set onAdopt(handler: (activity: Activity) => void | Promise<void>) {
        this._onAdopt = handler;
        this.render();
    }

    private async handleAdopt(): Promise<void> {
        const activity = this._activity;
        const onAdopt = this._onAdopt;
        if (!activity || !onAdopt) return;
        // Adoption is a POST; a second tap while it is in flight would race the unique
        // `external_id` index into a conflict the owner never needed to see. Story 371:
        // `onAdopt` resolves when the POST does, not when the event is dispatched.
        await whileBusy(this.shadowRoot!.getElementById('adopt') as HTMLButtonElement, () => onAdopt(activity));
    }

    set activity(val: Activity) {
        this._activity = val;
        this.render();
    }

    /**
     * Story 258: MET-estimated burn, shown with a `~` prefix when the row has
     * no recorded `calories_burned`. A recorded value always wins.
     */
    set estimatedBurnKcal(val: number | null) {
        this._estimatedBurnKcal = val;
        this.render();
    }

    private formatDuration(minutes?: number | null): string {
        if (!minutes) return '';
        if (minutes >= 60) {
            const h = Math.floor(minutes / 60);
            const m = minutes % 60;
            return m > 0 ? `${h}h ${m}min` : `${h}h`;
        }
        return `${minutes} min`;
    }

    private render() {
        const a = this._activity;
        if (!a) return;

        const shadow = this.shadowRoot!;

        shadow.getElementById('type-icon')!.textContent = activityIcon(a.type);
        shadow.getElementById('title')!.textContent = a.title;

        // Build meta line: start time · duration · calories · description
        const parts: string[] = [];
        const start = startTimeLabel(a.metadata);
        if (start) parts.push(start);
        const dur = this.formatDuration(a.duration_minutes);
        if (dur) parts.push(dur);
        if (a.calories_burned) {
            parts.push(`${formatMacro(a.calories_burned)} kcal`);
        } else if (this._estimatedBurnKcal != null && this._estimatedBurnKcal > 0) {
            parts.push(`~${formatMacro(this._estimatedBurnKcal)} kcal`);
        }
        if (a.description) parts.push(a.description);
        shadow.getElementById('meta')!.textContent = parts.join(' · ');

        const sourceEl = shadow.getElementById('source-badge')!;
        sourceEl.textContent = SOURCE_ICONS[a.source] ?? '❓';
        sourceEl.title = a.source.charAt(0).toUpperCase() + a.source.slice(1);

        // Only a class that is still just a calendar projection can be adopted — an adopted one is
        // a row like any other and opens the hub instead (story 323).
        const adoptEl = shadow.getElementById('adopt') as HTMLButtonElement;
        adoptEl.hidden = !this._onAdopt || !isSynthesizedCalendarEvent(a);
    }
}

/**
 * HH:MM start-of-activity label, or null when the row has no recorded start.
 *
 * Delegates to `activityStartLocalTime`, which projects `metadata.start` through the app
 * timezone. This used to be its own reader that preferred `start_date_local` and regex-sliced
 * `T(\d{2}:\d{2})` straight out of the raw string — which renders whatever wall clock the writer
 * happened to use. A Google Calendar event comes back in the zone it was created in (TRIB3's
 * booking system writes US-Eastern), so an 18:00 class was showing as 12:00. Two readers of one
 * field is what let them disagree; there is now one (stories 323/324).
 */
function startTimeLabel(metadata: string | null): string | null {
    return activityStartLocalTime(metadata) || null;
}

if (!customElements.get('activity-detail-card')) {
    customElements.define('activity-detail-card', ActivityDetailCard);
}
